class Node:
    def __init__(self, type: str):
        self.type = type
        self.inputs = []
        self.grad = None

    def _backward(self, grad):
        raise NotImplementedError

    def backward(self, grad=None):
        if grad:
            self.grad = grad
        self._backward(self.grad)
        for node in self.inputs:
            node.backward()

    def __str__(self):
        code = f"{self.type}("
        for node in self.inputs:
            code += f"{node}, "
        code = code + ")"
        return code


